function validate([grid, k]) {
  if (!Array.isArray(grid) || grid.length < 1) return 'grid needs at least one row.';
  const n = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (n < 1) return 'Each row needs at least one value.';
  if (grid.length * n > 50000) return 'grid has at most 50000 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== n) return 'All rows must have the same length.';
    if (row.some(v => !Number.isInteger(v) || v < 0 || v > 100)) return 'Each cell is an integer from 0 to 100.';
  }
  if (!Number.isInteger(k) || k < 1 || k > 50) return 'k is an integer from 1 to 50.';
  return null;
}

