function numberOfPaths(grid, k) {
  const MOD = 1000000007;
  const rows = grid.length;
  const cols = grid[0].length;
  const dp = Array.from({ length: rows }, () => Array.from({ length: cols }, () => new Array(k).fill(0)));
  dp[0][0][grid[0][0] % k] = 1;

  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (r === 0 && c === 0) {
        continue;
      }
      const cell = grid[r][c] % k;
      for (let rem = 0; rem < k; rem++) {
        const fromUp = r > 0 ? dp[r - 1][c][rem] : 0;
        const fromLeft = c > 0 ? dp[r][c - 1][rem] : 0;
        dp[r][c][(rem + cell) % k] = (fromUp + fromLeft) % MOD;
      }
    }
  }
  return dp[rows - 1][cols - 1][0];
}

