function numberOfPaths(grid, k) {
  // Walk every path explicitly, carrying its full (unreduced) sum.
  const m = grid.length, n = grid[0].length;
  let total = 0;
  const stack = [[0, 0, grid[0][0]]];
  while (stack.length) {
    const [i, j, sum] = stack.pop();
    if (i === m - 1 && j === n - 1) {
      if (sum % k === 0) total++;
      continue;
    }
    if (i + 1 < m) stack.push([i + 1, j, sum + grid[i + 1][j]]);
    if (j + 1 < n) stack.push([i, j + 1, sum + grid[i][j + 1]]);
  }
  return total % 1000000007;
}

