function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n, k, high;
  if (size === 'large') {
    const shape = rand();
    if (shape < 0.6) { m = int(80, 100); n = int(80, 100); }
    else if (shape < 0.8) { m = 1; n = int(1000, 2000); }
    else { m = int(1000, 2000); n = int(1, 10); }
    k = rand() < 0.5 ? int(1, 10) : int(11, 50);
    high = 100;
  } else {
    m = int(1, 4);
    n = int(1, 4);
    k = rand() < 0.7 ? int(1, 6) : int(7, 50);
    high = rand() < 0.5 ? 10 : 100;
  }
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < 0.15 ? 0 : int(0, high))));
  return [grid, k];
}
